Rule.Source:
import sailpoint.object.Identity;
  import sailpoint.object.Custom;
  import sailpoint.object.Application;
  import sailpoint.api.SailPointContext;
  import java.util.*;

  import org.apache.log4j.Logger;

  Logger log = Logger.getLogger("iiq.alpha.Alpha-Rule-LCEFaulireAlerting-WorkFlow-Rule");
  log.debug("Alpha-Rule-LCEFaulireAlerting-WorkFlow Rule - STARTS");


  Map failureMessagesMap = wfcontext.getVariable("alphaWorkflowFailureMap");
  log.debug("alphaWorkflowFailureMap:"+failureMessagesMap);

  if(null!=failureMessagesMap && failureMessagesMap.size()>0)
  {
    log.debug("Error Messages found in Workflow");
    Map argsMap = new HashMap();
    String joinerSuccessTo = null;
    Identity validManager = null;

    Identity identity = context.getObject(Identity.class,identityName);
    Identity validManager = getValidManagerRecursive(context,identity,"spadmin");

    String emailTemplate = (String) getValueFromCustomObject("Alpha-Custom-LCE Custom Object","LCE_Failure_emailTemplate"); 
    log.debug("emailTemplate :"+emailTemplate);
    log.debug("wfcase:"+wfcontext.getRootWorkflowCase());
    String taskName = wfcontext.getRootWorkflowCase().getTaskResult().getName();
    log.debug("taskName"+taskName);

    argsMap.put("taskName",taskName);
    argsMap.put("identity",identity);
    argsMap.put("failureMessagesMap",failureMessagesMap);

    String to = getValueFromCustomObject("Alpha-Custom-LCE Custom Object","LCE_Failure_NotifyGroup"); 
    String cc = validManager.getEmail();
    log.debug("to:"+to);
    log.debug("cc:"+cc);

    sendEmails(emailTemplate,to,cc,argsMap);


  }
  else{
    log.debug("No errors found in Joiner");
  }
